                "21000000026e5f73686f7274737472696e67333036000600000078787878780000",
                "21000000056e5f73686f7274737472696e67333036000500000000787878787800",
                "1d000000026e5f73686f7274737472696e673330360002000000ff0000",
                "18000000086e5f73686f7274737472696e67333036000100",
                "1c000000016f5f6d79666c6f617431303030001d4a9cf48782074800",
                "15000000086f5f6d79666c6f617431303030000100",
                "1e00000012705f6d7975696e7433325f3230303000000000000100000000",
                "1e00000001705f6d7975696e7433325f3230303000000000000000f83f00",
                "1700000008705f6d7975696e7433325f32303030000100",
                "2500000013715f6d79696e7436345f32303130000000000000000080000000000000403000",
                "1d00000001715f6d79696e7436345f3230313000000000000000f83f00",
                "1600000008715f6d79696e7436345f32303130000100",
                "1600000008725f6d79646f75626c6532303230000100",
            })
            {
                Check(!output.FromBson(FromHex(doc)), "accepted " + doc);
            }
            Check(output.Equals(MakeMessage()), "changed to " + output);
        }

        private static int RunTest(string name, Action test)
        {
            try
            {
                test();
            }
            catch (Exception e)
            {
                Console.WriteLine("FAIL ClassyMcClassface " + name + ": " + e.Message);
                return 1;
            }
            Console.WriteLine("PASS ClassyMcClassface " + name);
            return 0;
        }

        /// <summary>Runs every test, and returns the number that failed.</summary>
        public static int Run()
        {
            int failures = 0;
            failures += RunTest("RoundTrip", TestRoundTrip);
            failures += RunTest("Equals", TestEquals);
            failures += RunTest("ShortBuffer", TestShortBuffer);
            failures += RunTest("Offset", TestOffset);
            failures += RunTest("Wire", TestWire);
            failures += RunTest("Json", TestJson);
            failures += RunTest("JsonEmptyIsDefault", TestJsonEmptyIsDefault);
            failures += RunTest("JsonRejects", TestJsonRejects);
            failures += RunTest("Xml", TestXml);
            failures += RunTest("XmlEmptyIsDefault", TestXmlEmptyIsDefault);
            failures += RunTest("XmlRejects", TestXmlRejects);
            failures += RunTest("Bson", TestBson);
            failures += RunTest("BsonEmptyIsDefault", TestBsonEmptyIsDefault);
            failures += RunTest("BsonLargeUint64_h_myuint64_206", TestBsonLargeUint64_h_myuint64_206);
            failures += RunTest("BsonRejects", TestBsonRejects);
            return failures;
        }
#if !SKYWIRE_NO_MAIN

        public static int Main()
        {
            return Run() == 0 ? 0 : 1;
        }
#endif
    }
